// ─── Admin Auth ───────────────────────────────────────────────────────────────
export const adminLogin = async (password) => {
    try {
        const response = await api.post('/admin/login', { password });
        if (response.data.success && response.data.token) {
            localStorage.setItem(KEYS.ADMIN, 'true');
            localStorage.setItem(KEYS.TOKEN, response.data.token);
            if (response.data.role) {
                localStorage.setItem(KEYS.ROLE, response.data.role);
            }
            return true;
        }
        return false;
    } catch (error) {
        console.error("Admin login error", error);
        return false;
    }
};

export const adminLogout = () => {
    localStorage.removeItem(KEYS.ADMIN);
    localStorage.removeItem(KEYS.TOKEN);
    localStorage.removeItem(KEYS.ROLE);
};

export const isAdminLoggedIn = () =>
    typeof window !== 'undefined' && localStorage.getItem(KEYS.ADMIN) === 'true';

export const getAdminRole = () =>
    (typeof window !== 'undefined' ? localStorage.getItem(KEYS.ROLE) : null) || 'admin';

